Matching Ayahs
- = Alif, Lam, Mim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Zij zijn op de rechte weg van hun Heer, en zij zijn degenen die slagen. 2:5; 31:5
- = O kinderen van Israël, gedenkt Mijn gunst die Ik jullie heb geschonken en dat Ik jullie boven de werelden (volkeren) heb verkozen. 2:47; 2:122
- = Dat was een volk dat voorbij is gegaan. Het zal krijgen wat het verdiende, en jullie zullen krijgen wat jullie verdiend hebben. En jullie zullen niet worden ondervraagd over wat zij plachten te doen. 2:134; 2:141
- = Zij zullen er eeuwig in verblijven. De straf zal voor hen niet worden verlicht, en zij zullen geen uitstel krijgen. 2:162; 3:88
- = Behalve degenen die daarna berouw tonen en zichzelf verbeteren. Voorwaar, Allah is Vergevensgezind, Barmhartig. 3:89; 24:5
